	publicAPI.replaceShaderTCoord = (hash, pipeline, vertexInput) => {
		if (!vertexInput.hasAttribute("tcoord")) return;
		const vDesc = pipeline.getShaderDescription("vertex");
		const arrayInfo = vertexInput.getBuffer("tcoord").getArrayInformation()[0];
		const numComp = Types/* ["default"].getNumberOfComponentsFromBufferFormat */.A.getNumberOfComponentsFromBufferFormat(arrayInfo.format);
		const interpolation = arrayInfo.interpolation;
		let code = vDesc.getCode();
		vDesc.addOutput(`vec${numComp}<f32>`, "tcoordVS", interpolation);
		code = ShaderCache/* ["default"].substitute */.Ay.substitute(code, "//VTK::TCoord::Impl", ["  output.tcoordVS = tcoord;"]).result;
		vDesc.setCode(code);
		const fDesc = pipeline.getShaderDescription("fragment");
		code = fDesc.getCode();
		const actor = model.WebGPUActor.getRenderable();
		const property = actor.getProperty();
		const checkDims = (texture) => {
			if (!texture) return false;
			return texture.getDimensionality() === numComp;
		};
		const usedTextures = [];
		const diffuseTexture = property.getDiffuseTexture?.();
		if (diffuseTexture?.getImageLoaded() || actor.getTextures()[0] || model.colorTexture) {
			if (checkDims(diffuseTexture) || checkDims(actor.getTextures()[0]) || checkDims(model.colorTexture)) usedTextures.push("_diffuseMap = textureSample(DiffuseTexture, DiffuseTextureSampler, input.tcoordVS);");
		}
		const ormTexture = property.getORMTexture?.();
		const rmTexture = property.getRMTexture?.();
		const roughnessTexture = property.getRoughnessTexture?.();
		const metallicTexture = property.getMetallicTexture?.();
		const ambientOcclusionTexture = property.getAmbientOcclusionTexture?.();
		const emissionTexture = property.getEmissionTexture?.();
		const normalTexture = property.getNormalTexture?.();
		if (ormTexture?.getImageLoaded()) {
			if (checkDims(ormTexture)) usedTextures.push("let ormSample = textureSample(ORMTexture, ORMTextureSampler, input.tcoordVS);", "_ambientOcclusionMap = ormSample.rrra;", "_roughnessMap = ormSample.ggga;", "_metallicMap = ormSample.bbba;");
		} else if (rmTexture?.getImageLoaded()) {
			if (checkDims(rmTexture)) usedTextures.push("let rmSample = textureSample(RMTexture, RMTextureSampler, input.tcoordVS);", "_roughnessMap = rmSample.ggga;", "_metallicMap = rmSample.bbba;");
		} else {
			if (roughnessTexture?.getImageLoaded()) {
				if (checkDims(roughnessTexture)) usedTextures.push("_roughnessMap = textureSample(RoughnessTexture, RoughnessTextureSampler, input.tcoordVS).ggga;");
			}
			if (metallicTexture?.getImageLoaded()) {
				if (checkDims(metallicTexture)) usedTextures.push("_metallicMap = textureSample(MetallicTexture, MetallicTextureSampler, input.tcoordVS).bbba;");
			}
			if (ambientOcclusionTexture?.getImageLoaded()) {
				if (checkDims(ambientOcclusionTexture)) usedTextures.push("_ambientOcclusionMap = textureSample(AmbientOcclusionTexture, AmbientOcclusionTextureSampler, input.tcoordVS).rrra;");
			}
		}
		if (emissionTexture?.getImageLoaded()) {
			if (checkDims(emissionTexture)) usedTextures.push("_emissionMap = textureSample(EmissionTexture, EmissionTextureSampler, input.tcoordVS);");
		}
		if (normalTexture?.getImageLoaded()) {
			if (checkDims(normalTexture)) usedTextures.push("_normalMap = textureSample(NormalTexture, NormalTextureSampler, input.tcoordVS);");
		}
		code = ShaderCache/* ["default"].substitute */.Ay.substitute(code, "//VTK::TCoord::Impl", usedTextures).result;
		fDesc.setCode(code);
	};
